insert into public.fiscal_rtc_classifications (
  tax_kind, cst, cclass_trib, description, indicators, nt_version, table_version,
  source_url, source_sha256, valid_from, valid_until, active
)
select
  'IS', left(item->>'codigo', 3), item->>'codigo', item->>'descricao', item,
  'Calculadora de Tributos sobre o Consumo', '2027-01-01',
  'https://piloto-cbs.tributos.gov.br/servico/calculadora-consumo/api/calculadora/dados-abertos/classificacoes-tributarias/imposto-seletivo?data=2027-01-01',
  'ba055b6004a10db5205760bef5ed67bf4af75565ba9378b583a633e14cc57559', '2027-01-01', null, true
from source_rows
on conflict (tax_kind, cst, cclass_trib, table_version) do update set
  description = excluded.description, indicators = excluded.indicators, nt_version = excluded.nt_version,
  source_url = excluded.source_url, source_sha256 = excluded.source_sha256,
  valid_from = excluded.valid_from, valid_until = excluded.valid_until, active = true, imported_at = now();

alter table public.fiscal_tax_rules
  drop constraint if exists fiscal_tax_rules_product_origin_catalog,
  add constraint fiscal_tax_rules_product_origin_catalog check (
    product_origin is null or product_origin between 0 and 8
  ) not valid,
  drop constraint if exists fiscal_tax_rules_icms_code_catalog,
  add constraint fiscal_tax_rules_icms_code_catalog check (
    icms_code = any(array['101','102','103','201','202','203','300','400','500','900','00','10','20','30','40','41','50','51','60','70','90'])
  ) not valid;
